// Format daily summary email
const stats = $json;
const totalTrades = parseInt(stats.total_trades) || 0;
const wins = parseInt(stats.wins) || 0;
const losses = parseInt(stats.losses) || 0;
const profit = parseFloat(stats.total_profit) || 0;
const avgConfidence = parseFloat(stats.avg_confidence) || 0;
const winRate = totalTrades > 0 ? (wins / totalTrades * 100).toFixed(1) : 0;
const isProfit = profit >= 0;

const subject = `📊 Daily Trading Summary - ${wins}W/${losses}L | ${isProfit ? '+' : ''}$${profit.toFixed(2)}`;

const html = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .container { max-width: 600px; margin: 0 auto; padding: 20px; }
    .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; border-radius: 10px; text-align: center; }
    .stats-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 15px; margin: 20px 0; }
    .stat-card { background: #f8f9fa; padding: 20px; border-radius: 8px; text-align: center; border: 2px solid #e9ecef; }
    .stat-value { font-size: 32px; font-weight: bold; color: #495057; margin: 10px 0; }
    .stat-label { font-size: 14px; color: #6c757d; text-transform: uppercase; }
    .profit-card { background: ${isProfit ? '#d4edda' : '#f8d7da'}; border-color: ${isProfit ? '#28a745' : '#dc3545'}; }
    .profit-value { color: ${isProfit ? '#28a745' : '#dc3545'}; }
    .footer { text-align: center; color: #6c757d; font-size: 12px; margin-top: 30px; padding-top: 20px; border-top: 1px solid #dee2e6; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>📊 Daily Trading Summary</h1>
      <p style="margin: 0; font-size: 18px;">${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
    </div>

    <div class="stats-grid">
      <div class="stat-card">
        <div class="stat-label">Total Trades</div>
        <div class="stat-value">${totalTrades}</div>
      </div>

      <div class="stat-card">
        <div class="stat-label">Win Rate</div>
        <div class="stat-value">${winRate}%</div>
      </div>

      <div class="stat-card">
        <div class="stat-label">Wins</div>
        <div class="stat-value" style="color: #28a745;">${wins}</div>
      </div>

      <div class="stat-card">
        <div class="stat-label">Losses</div>
        <div class="stat-value" style="color: #dc3545;">${losses}</div>
      </div>

      <div class="stat-card profit-card" style="grid-column: 1 / -1;">
        <div class="stat-label">Total Profit/Loss</div>
        <div class="stat-value profit-value">${isProfit ? '+' : ''}$${profit.toFixed(2)}</div>
      </div>

      <div class="stat-card" style="grid-column: 1 / -1;">
        <div class="stat-label">Average AI Confidence</div>
        <div class="stat-value">${avgConfidence.toFixed(1)}%</div>
      </div>
    </div>

    <div style="background: #e7f3ff; padding: 20px; border-radius: 8px; margin: 20px 0;">
      <h3 style="margin-top: 0; color: #004085;">📈 Performance Insights</h3>
      <ul style="margin: 10px 0; padding-left: 20px;">
        <li>${totalTrades > 0 ? 'System executed ' + totalTrades + ' trades today' : 'No trades executed today'}</li>
        <li>Win rate: ${winRate}% ${parseFloat(winRate) >= 60 ? '(Good)' : parseFloat(winRate) >= 50 ? '(Fair)' : '(Needs improvement)'}</li>
        <li>Net result: ${isProfit ? 'Profitable day ✅' : 'Loss day ⚠️'}</li>
        <li>AI confidence averaged ${avgConfidence.toFixed(1)}%</li>
      </ul>
    </div>

    <div class="footer">
      <p>🤖 IQOption AI Trading System</p>
      <p>Generated at ${new Date().toISOString()}</p>
      <p>This is an automated daily report. Do not reply to this email.</p>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    subject: subject,
    html: html,
    email_to: $env.N8N_EMAIL_TO,
    stats: stats
  }
}];
